/* Simulateur de rééquilibrage — actions / obligations */
(function () {
  var svg = document.getElementById("rb-bar");
  if (!svg) return;
  function v(id){ return parseFloat(document.getElementById(id).value); }
  function setT(id,t){ var e=document.getElementById(id); if(e) e.textContent=t; }
  function activeLang(){ return document.body.getAttribute("data-active-lang") || "fr"; }

  var MSG = {
    ok:   {fr:"✔ Dans la bande — aucun rééquilibrage nécessaire.", en:"✔ Within the band — no rebalancing needed.", nl:"✔ Binnen de band — geen herbalancering nodig."},
    sell: {fr:"⚠ Bande franchie — vendre ", en:"⚠ Band breached — sell ", nl:"⚠ Band overschreden — verkoop "},
    buy:  {fr:"⚠ Bande franchie — acheter ", en:"⚠ Band breached — buy ", nl:"⚠ Band overschreden — koop "},
    tail: {fr:" € d'actions pour revenir à la cible.", en:" of equities to return to target.", nl:" aan aandelen om terug te keren naar het doel."}
  };

  function draw() {
    var w=v("rb-w")/100, rs=v("rb-rs")/100, rb=v("rb-rb")/100, band=v("rb-band");
    setT("rb-w-o", v("rb-w")+"%"); setT("rb-rs-o", v("rb-rs")+"%"); setT("rb-rb-o", v("rb-rb")+"%"); setT("rb-band-o", v("rb-band").toFixed(1).replace(/\.0$/,"")+" pt");

    var V=100000;
    var sVal=V*w*(1+rs), bVal=V*(1-w)*(1+rb), tot=sVal+bVal;
    var wNew= tot>0 ? sVal/tot : 0;
    var dev=(wNew-w)*100;
    setT("rb-drift", (wNew*100).toFixed(1)+"%");
    setT("rb-dev", (dev>=0?"+":"")+dev.toFixed(1)+" pt");

    var L=activeLang();
    var vEl=document.getElementById("rb-verdict");
    if (Math.abs(dev) <= band){
      vEl.textContent = MSG.ok[L]; vEl.style.color="var(--ok, #2f8f6a)";
    } else {
      var targetS=tot*w, trade=targetS - sVal; // <0 sell equities
      var amt=Math.abs(trade);
      var pre = trade<0 ? MSG.sell[L] : MSG.buy[L];
      vEl.textContent = pre + Math.round(amt).toLocaleString(L==="en"?"en-US":(L==="nl"?"nl-BE":"fr-FR")) + MSG.tail[L];
      vEl.style.color="var(--crimson, #b23a48)";
    }

    // bar : current stock/bond split after drift, with target marker
    var W=520,H=56,y=16,h=24;
    var sw=wNew*W;
    var g='';
    g+='<rect x="0" y="'+y+'" width="'+sw.toFixed(1)+'" height="'+h+'" fill="#12294a"/>';
    g+='<rect x="'+sw.toFixed(1)+'" y="'+y+'" width="'+(W-sw).toFixed(1)+'" height="'+h+'" fill="#c19a3e"/>';
    if (sw>34) g+='<text x="'+(sw/2)+'" y="'+(y+16)+'" text-anchor="middle" fill="#fff" font-size="11" font-family="var(--sans)" font-weight="600">'+(wNew*100).toFixed(0)+'%</text>';
    if (W-sw>34) g+='<text x="'+(sw+(W-sw)/2)+'" y="'+(y+16)+'" text-anchor="middle" fill="#fff" font-size="11" font-family="var(--sans)" font-weight="600">'+((1-wNew)*100).toFixed(0)+'%</text>';
    // target marker
    var tx=w*W;
    g+='<line x1="'+tx.toFixed(1)+'" y1="'+(y-6)+'" x2="'+tx.toFixed(1)+'" y2="'+(y+h+6)+'" stroke="var(--ink)" stroke-width="2"/>';
    g+='<text x="'+tx.toFixed(1)+'" y="'+(y+h+18)+'" text-anchor="middle" fill="var(--ink-soft)" font-size="10" font-family="var(--sans)">'+(activeLang()==="en"?"target":(activeLang()==="nl"?"doel":"cible"))+' '+(w*100).toFixed(0)+'%</text>';
    svg.innerHTML=g;
  }

  ["rb-w","rb-rs","rb-rb","rb-band"].forEach(function(id){ var e=document.getElementById(id); if(e) e.addEventListener("input", draw); });
  document.querySelectorAll("[data-set-lang]").forEach(function(b){ b.addEventListener("click", function(){ setTimeout(draw,10); }); });
  document.addEventListener("DOMContentLoaded", draw);
  draw();
})();
